(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      duration: ${duration},
      glitchIntensity: ${glitchIntensity},
      rgbShiftAmount: ${rgbShiftAmount},
      scanlineCount: ${scanlineCount}
    };
    var transitionLayer = comp.layers.addSolid([0, 0, 0], "Glitch Transition", comp.width, comp.height, 1);
    transitionLayer.inPoint = comp.time;
    transitionLayer.outPoint = comp.time + p.duration;
    transitionLayer.opacity.setValueAtTime(comp.time, 100);
    transitionLayer.opacity.setValueAtTime(comp.time + p.duration, 0);
    var shift = transitionLayer.Effects.addProperty("ADBE Shift Channels");
    shift.property("ADBE Shift Channels-0001").setValue("Red");
    shift.property("ADBE Shift Channels-0002").setValue("Green");
    shift.property("ADBE Shift Channels-0003").setValue("Blue");
    var cc = transitionLayer.Effects.addProperty("ADBE Channel Combiner");
    _result = {status:"success", message:"赛博朋克故障转场已创建"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      duration: ${duration},
      fadeColor: ${fadeColor},
      easing: ${easing}
    };
    var fadeLayer = comp.layers.addSolid(p.fadeColor, "Film Fade", comp.width, comp.height, 1);
    fadeLayer.inPoint = comp.time;
    fadeLayer.outPoint = comp.time + p.duration;
    fadeLayer.opacity.setValueAtTime(comp.time, 0);
    fadeLayer.opacity.setValueAtTime(comp.time + p.duration / 2, 100);
    fadeLayer.opacity.setValueAtTime(comp.time + p.duration, 0);
    for (var k = 1; k <= fadeLayer.opacity.numKeys; k++) {
      fadeLayer.opacity.setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    }
    _result = {status:"success", message:"电影淡入淡出转场已创建"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

