(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      duration: ${duration},
      direction: ${direction},
      easing: ${easing}
    };
    var slideLayer = comp.layers.addSolid([0.5, 0.5, 0.5], "Slide Transition", comp.width, comp.height, 1);
    slideLayer.inPoint = comp.time;
    slideLayer.outPoint = comp.time + p.duration;
    var pos = slideLayer.property("Position");
    var startX = p.direction === "right" ? -comp.width : (p.direction === "left" ? comp.width * 2 : comp.width / 2);
    var startY = p.direction === "up" ? comp.height * 2 : (p.direction === "down" ? -comp.height : comp.height / 2);
    pos.setValueAtTime(comp.time, [startX, comp.height / 2]);
    pos.setValueAtTime(comp.time + p.duration, [comp.width / 2, comp.height / 2]);
    for (var k = 1; k <= pos.numKeys; k++) {
      pos.setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    }
    _result = {status:"success", message:"滑动转场已创建"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

(function() {
