      flipAxis: ${flipAxis},
      perspective: ${perspective}
    };
    var flipLayer = comp.layers.addSolid([1, 1, 1], "Page Flip", comp.width, comp.height, 1);
    flipLayer.inPoint = comp.time;
    flipLayer.outPoint = comp.time + p.duration;
    flipLayer.threeDLayer = true;
    comp.activeCamera.pointOfInterest.setValue([comp.width / 2, comp.height / 2, 0]);
    comp.activeCamera.position.setValue([comp.width / 2, comp.height / 2, p.perspective]);
    var rotation = flipLayer.property("Rotation");
    rotation.setValueAtTime(comp.time, p.flipAxis === "horizontal" ? [0, 0, 0] : [0, 0, 0]);
    rotation.setValueAtTime(comp.time + p.duration, p.flipAxis === "horizontal" ? [0, 360, 0] : [360, 0, 0]);
    _result = {status:"success", message:"翻页转场已创建"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
