(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {
      duration: ${duration},
      flashColor: ${flashColor},
      peakIntensity: ${peakIntensity},
      flashCount: ${flashCount},
      fadeSpeed: ${fadeSpeed}
    };
    var flashLayer = comp.layers.addSolid(p.flashColor, "Flash Cut", comp.width, comp.height, 1);
    flashLayer.inPoint = comp.time;
    flashLayer.outPoint = comp.time + p.duration;
    var segDur = p.duration / p.flashCount;
    for (var i = 0; i < p.flashCount; i++) {
      var t0 = comp.time + i * segDur;
      var t1 = t0 + segDur * p.fadeSpeed;
      flashLayer.opacity.setValueAtTime(t0, 0);
      flashLayer.opacity.setValueAtTime(t0 + segDur * 0.1, p.peakIntensity);
      flashLayer.opacity.setValueAtTime(t1, 0);
    }
    for (var k = 1; k <= flashLayer.opacity.numKeys; k++) {
      flashLayer.opacity.setInterpolationTypeAtKey(k, KeyframeInterpolationType.LINEAR, KeyframeInterpolationType.LINEAR);
    }
    flashLayer.blendingMode = BlendingMode.ADD;
    _result = {status:"success", message:"闪光切换转场已创建"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

