      return JSON.stringify(_result);
    }
    var p = {
      duration: ${duration},
      squashAmount: ${squashAmount},
      stretchAmount: ${stretchAmount},
      axis: ${axis}
    };
    var deformLayer = comp.layers.addSolid([0.5, 0.5, 0.5], "Squash Stretch", comp.width, comp.height, 1);
    deformLayer.inPoint = comp.time;
    deformLayer.outPoint = comp.time + p.duration;
    var sc = deformLayer.property("Scale");
    var t3 = comp.time + p.duration * 0.33;
    var t6 = comp.time + p.duration * 0.67;
    if (p.axis === "horizontal") {
      sc.setValueAtTime(comp.time, [100, 100]);
      sc.setValueAtTime(t3, [100 + p.squashAmount, 100 - p.squashAmount * 0.5]);
      sc.setValueAtTime(t6, [100 - p.stretchAmount, 100 + p.stretchAmount * 0.5]);
      sc.setValueAtTime(comp.time + p.duration, [100, 100]);
    } else {
      sc.setValueAtTime(comp.time, [100, 100]);
      sc.setValueAtTime(t3, [100 - p.squashAmount * 0.5, 100 + p.squashAmount]);
      sc.setValueAtTime(t6, [100 + p.stretchAmount * 0.5, 100 - p.stretchAmount]);
      sc.setValueAtTime(comp.time + p.duration, [100, 100]);
    }
    for (var k = 1; k <= sc.numKeys; k++) {
      sc.setInterpolationTypeAtKey(k, KeyframeInterpolationType.BEZIER, KeyframeInterpolationType.BEZIER);
    }
    _result = {status:"success", message:"挤压拉伸转场已创建"};
