      endScale: ${endScale}
    };
    var adj = comp.layers.addAdjustmentLayer();
    adj.name = "Rect Mask";
    adj.inPoint = comp.time;
    adj.outPoint = comp.time + p.duration;
    var sc = adj.property("Scale");
    sc.setValueAtTime(comp.time, [p.startScale, p.startScale]);
    sc.setValueAtTime(comp.time + p.duration, [p.endScale, p.endScale]);
    var mask = adj.Masks.addProperty("ADBE Mask Atom");
    mask.maskMode = MaskMode.ADD;
    mask.maskFeather.setValue([p.feather, p.feather]);
    _result = {status:"success", message:"矩形遮罩转场已创建"};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

